  1→@import "tailwindcss";
  2→
  3→/**
  4→ * GOLDEN RATIO DESIGN SYSTEM
  5→ *
  6→ * Spacing follows Fibonacci sequence (approximates φ = 1.618):
  7→ * - 21, 34, 55, 89, 144, 233px
  8→ * - Each value × 1.618 ≈ next value
  9→ *
 10→ * Blends production warmth with Pentagram refinement:
 11→ * - Dark theme with warm amber accent
 12→ * - Golden ratio spacing throughout
 13→ * - Editorial typography with warmth
 14→ * - Refined interactions
 15→ */
 16→
 17→:root {
 18→  /* Golden Ratio: φ = 1.618, 1/φ = 0.618 */
 19→  --phi: 1.618;
 20→  --phi-inverse: 0.618;
 21→
 22→  /* Fibonacci spacing scale (each × φ ≈ next) */
 23→  --space-xs: 21px;    /* Fibonacci */
 24→  --space-sm: 34px;    /* 21 × 1.618 ≈ 34 */
 25→  --space-md: 55px;    /* 34 × 1.618 ≈ 55 */
 26→  --space-lg: 89px;    /* 55 × 1.618 ≈ 89 */
 27→  --space-xl: 144px;   /* 89 × 1.618 ≈ 144 */
 28→  --space-2xl: 233px;  /* 144 × 1.618 ≈ 233 */
 29→
 30→  /* Typography - Helvetica Neue alternative */
 31→  /* Inter: neo-grotesque sans-serif, clean, neutral, screen-optimized */
 32→  --font-display: var(--font-inter), 'Inter', sans-serif;
 33→  --font-body: var(--font-inter), 'Inter', sans-serif;
 34→
 35→  /* Color palette - Dark with warm accent */
 36→  --background: #141414;
 37→  --foreground: #b8b8b8;
 38→  --text-primary: #e8e8e8;
 39→  --text-secondary: #8a8a8a;  /* Consolidated from #888888, #8a8a8a */
 40→  --text-muted: #6a6a6a;      /* Consolidated from #666666, #6a6a6a */
 41→  --text-dim: #5a5a5a;        /* NEW: For subtle labels, tags */
 42→  --border: #2a2a2a;
 43→  --border-subtle: #222222;   /* NEW: For subtle dividers */
 44→  --surface: #1a1a1a;         /* NEW: Elevated surface (cards, tags) */
 45→  --accent: #d4a853;          /* Warm gold - refined amber */
 46→  --accent-subtle: rgba(212, 168, 83, 0.15);
 47→
 48→  /* ═══════════════════════════════════════════════════════════════
 49→     COLOR HIERARCHY MANTRA
 50→     Information hierarchy = Color hierarchy
 51→
 52→     PRIMARY:   --text-primary (#e8e8e8) — Titles, headings, anchors
 53→     SECONDARY: --grey-500 (#7a7a7a)     — Descriptions, body content
 54→     TERTIARY:  --text-dim (#5a5a5a)     — Metadata, labels, footnotes
 55→
 56→     Rule: Brighter = more important. Dimmer = supporting context.
 57→     ═══════════════════════════════════════════════════════════════ */
 58→
 59→  /* Grey scale - Deterministic (use these, not hex values) */
 60→  --grey-50: #f0f0f0;   /* Brightest text */
 61→  --grey-100: #e8e8e8;  /* Primary text (= --text-primary) — TITLES */
 62→  --grey-200: #c0c0c0;  /* Emphasis text */
 63→  --grey-300: #a0a0a0;  /* Light secondary */
 64→  --grey-400: #8a8a8a;  /* Secondary text (= --text-secondary) */
 65→  --grey-500: #7a7a7a;  /* Medium grey — DESCRIPTIONS */
 66→  --grey-600: #6a6a6a;  /* Muted text (= --text-muted) */
 67→  --grey-700: #5a5a5a;  /* Dim text (= --text-dim) — METADATA */
 68→  --grey-800: #3a3a3a;  /* Separator dots */
 69→  --grey-900: #2a2a2a;  /* Borders (= --border) */
 70→
 71→  /* Micro spacing - for elements smaller than Fibonacci scale */
 72→  --space-micro: 4px;   /* Padding inside small elements */
 73→  --space-tiny: 8px;    /* Small gaps */
 74→  --space-small: 13px;  /* 21 / phi ≈ 13 */
 75→
 76→  /* Border radius scale - 3 values only */
 77→  --radius-sm: 4px;     /* Tags, buttons, code blocks */
 78→  --radius-md: 6px;     /* Thumbnails, cards */
 79→  --radius-full: 50%;   /* Circles, avatars */
 80→
 81→  /* Standardized transitions */
 82→  --transition-fast: 200ms ease-out;
 83→  --transition-base: 300ms ease-out;
 84→  --transition-smooth: 400ms cubic-bezier(0.25, 0.1, 0.25, 1);
 85→
 86→  /* Standardized hover opacity */
 87→  --hover-dim: 0.6;
 88→}
 89→
 90→@theme inline {
 91→  --color-background: var(--background);
 92→  --color-foreground: var(--foreground);
 93→  --font-sans: var(--font-inter);
 94→
 95→  /* Golden ratio spacing */
 96→  --spacing-section: var(--space-lg);  /* 89px */
 97→  --spacing-gutter: var(--space-md);   /* 55px */
 98→
 99→  /* Layout - balanced width */
100→  --max-content-width: 1600px;
101→  --side-padding: clamp(24px, 3vw, 80px);     /* Fluid: scales with viewport */
102→  --side-padding-md: clamp(34px, 4vw, 100px);  /* Fluid: scales with viewport */
103→}
104→
105→/* Typography */
106→body {
107→  background: var(--background);
108→  color: var(--foreground);
109→  font-family: var(--font-body), -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
110→  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
111→  -webkit-font-smoothing: antialiased;
112→  -moz-osx-font-smoothing: grayscale;
113→}
114→
115→h1, h2, h3, h4, h5, h6, p {
116→  margin: 0;
117→  font-weight: 400;
118→}
119→
120→h1, h2, h3 {
121→  text-wrap: balance;
122→}
123→
124→button {
125→  border: none;
126→  font: inherit;
127→  cursor: pointer;
128→}
129→
130→html {
131→  scroll-behavior: smooth;
132→  background-color: var(--background);
133→}
134→
135→/* ===========================================
136→   PROJECT CARD INTERACTIONS
137→   =========================================== */
138→
139→/* Hover overlay and transitions handled inline in ProjectCard.tsx and VideoThumbnail.tsx */
140→/* This keeps all visual logic colocated with the component for easier maintenance */
141→
142→/* ===========================================
143→   NAVIGATION INTERACTIONS
144→   =========================================== */
145→
146→.nav-link {
147→  position: relative;
148→  display: inline-block;
149→  text-decoration: none;
150→  /* Reversed hover: full opacity by default, dims on hover */
151→  opacity: 1;
152→  transition: opacity var(--transition-smooth);
153→}
154→
155→@media (hover: hover) and (pointer: fine) {
156→  .nav-link:hover {
157→    opacity: var(--hover-dim);
158→  }
159→}
160→
161→/* Section headers - Light table effect */
162→.section-header-highlight {
163→  position: relative;
164→  display: inline-block;
165→  /* Light table: dimmed by default, reveals on hover */
166→  opacity: 0.5;
167→  transition: opacity var(--transition-smooth);
168→}
169→
170→@media (hover: hover) and (pointer: fine) {
171→  .section-header-highlight:hover {
172→    opacity: 1;
173→  }
174→}
175→
176→.nav-item-shift {
177→  transition: opacity var(--transition-smooth);
178→}
179→
180→/* Button arrow */
181→.button-arrow-shift {
182→  display: inline-flex;
183→  align-items: center;
184→  gap: var(--space-tiny);
185→}
186→
187→.button-arrow {
188→  transition: transform var(--transition-smooth), opacity var(--transition-smooth);
189→  opacity: 0.5;
190→}
191→
192→@media (hover: hover) and (pointer: fine) {
193→  .button-arrow-shift:hover .button-arrow {
194→    transform: translateX(4px);
195→    opacity: 1;
196→  }
197→}
198→
199→.gpu-accelerated {
200→  will-change: transform;
201→  transform: translateZ(0);
202→  backface-visibility: hidden;
203→}
204→
205→/* Vimeo iframe: force dark background before video loads (prevents white flash) */
206→iframe[src*="vimeo"],
207→iframe[src*="player.vimeo"] {
208→  background-color: #141414;
209→  border: none;
210→  display: block;
211→}
212→
213→/* ===========================================
214→   ENTRANCE ANIMATIONS
215→   =========================================== */
216→
217→@keyframes fadeUp {
218→  from {
219→    opacity: 0;
220→    transform: translateY(21px);  /* Fibonacci */
221→  }
222→  to {
223→    opacity: 1;
224→    transform: translateY(0);
225→  }
226→}
227→
228→.project-card {
229→  opacity: 0;
230→  animation: fadeUp 0.7s ease-out forwards;
231→}
232→
233→.project-card:nth-child(1) { animation-delay: 0ms; }
234→.project-card:nth-child(2) { animation-delay: 80ms; }
235→.project-card:nth-child(3) { animation-delay: 160ms; }
236→.project-card:nth-child(4) { animation-delay: 240ms; }
237→.project-card:nth-child(5) { animation-delay: 320ms; }
238→.project-card:nth-child(6) { animation-delay: 400ms; }
239→
240→@keyframes fadeIn {
241→  from { opacity: 0; }
242→  to { opacity: 1; }
243→}
244→
245→.client-strip {
246→  animation: fadeIn 0.8s ease-out forwards;
247→  animation-delay: 200ms;
248→  opacity: 0;
249→}
250→
251→/* Scroll indicator */
252→@keyframes scrollFloat {
253→  0%, 100% {
254→    transform: translateY(0);
255→    opacity: 0.5;
256→  }
257→  50% {
258→    transform: translateY(6px);
259→    opacity: 0.8;
260→  }
261→}
262→
263→.scroll-chevron {
264→  animation: scrollFloat 2.8s ease-in-out infinite;
265→  will-change: transform, opacity;
266→}
267→
268→/* Chat typing indicator */
269→@keyframes typingPulse {
270→  0%, 100% {
271→    opacity: 0.3;
272→    transform: scale(1);
273→  }
274→  50% {
275→    opacity: 1;
276→    transform: scale(1.15);
277→  }
278→}
279→
280→.typing-dot {
281→  will-change: transform, opacity;
282→}
283→
284→/* Chat message entrance */
285→@keyframes chatMessageIn {
286→  from {
287→    opacity: 0;
288→    transform: translateY(13px);  /* --space-small: 21 / phi */
289→  }
290→  to {
291→    opacity: 1;
292→    transform: translateY(0);
293→  }
294→}
295→
296→.chat-message-enter {
297→  animation: chatMessageIn 0.3s ease-out forwards;
298→}
299→
300→/* Reduced motion */
301→@media (prefers-reduced-motion: reduce) {
302→  html {
303→    scroll-behavior: auto;
304→  }
305→
306→  *,
307→  *::before,
308→  *::after {
309→    animation-duration: 0.01ms !important;
310→    animation-iteration-count: 1 !important;
311→    transition-duration: 0.01ms !important;
312→  }
313→
314→  [aria-live="polite"] {
315→    transition: none !important;
316→  }
317→
318→  .nav-link,
319→  .project-title h3,
320→  .section-header-highlight,
321→  .project-card,
322→  .nav-item-shift,
323→  .button-arrow,
324→  .scroll-chevron,
325→  .typing-dot,
326→  .chat-message-enter {
327→    transition: none !important;
328→    transform: none !important;
329→    animation: none !important;
330→  }
331→}
332→
333→/* ===========================================
334→   FOCUS INDICATORS FOR ACCESSIBILITY
335→   =========================================== */
336→
337→/* Focus-visible indicators for keyboard navigation */
338→:focus-visible {
339→  outline: 2px solid rgba(255, 255, 255, 0.5);
340→  outline-offset: 2px;
341→}
342→
343→/* Remove focus ring on mouse click, keep for keyboard */
344→:focus:not(:focus-visible) {
345→  outline: none;
346→}
347→
348→/* ===========================================
349→   VIEW TRANSITIONS - Cinematic Page Crossfades
350→   =========================================== */
351→
352→/*
353→ * Design philosophy:
354→ * - Film dissolve feel, not flashy web animation
355→ * - Content: subtle crossfade with micro-scale for depth
356→ * - Navigation: fade only (no scale/position change - stays anchored)
357→ * - Duration: 500ms content, 400ms nav (slow enough to feel intentional)
358→ * - Easing: ease-in-out for cinematic linear-ish blend
359→ */
360→
361→/* Dark canvas behind all transition layers — prevents white bleed-through */
362→::view-transition {
363→  background-color: #141414;
364→}
365→
366→::view-transition-group(root),
367→::view-transition-group(navigation),
368→::view-transition-group(footer) {
369→  background-color: #141414;
370→}
371→
372→/* Root (main content) transition */
373→::view-transition-old(root),
374→::view-transition-new(root) {
375→  animation-duration: 500ms;
376→  animation-timing-function: ease-in-out;
377→}
378→
379→/* Old page: fade out with slight scale down */
380→::view-transition-old(root) {
381→  animation-name: fade-and-scale-out;
382→}
383→
384→/* New page: fade in with slight scale up */
385→::view-transition-new(root) {
386→  animation-name: fade-and-scale-in;
387→}
388→
389→@keyframes fade-and-scale-out {
390→  from {
391→    opacity: 1;
392→    transform: scale(1);
393→  }
394→  to {
395→    opacity: 0;
396→    transform: scale(0.98);
397→  }
398→}
399→
400→@keyframes fade-and-scale-in {
401→  from {
402→    opacity: 0;
403→    transform: scale(1.02);
404→  }
405→  to {
406→    opacity: 1;
407→    transform: scale(1);
408→  }
409→}
410→
411→/* Navigation: fade only, no scale (stays anchored) */
