  3→/**
  4→ * Perception Context
  5→ * Phase 2: USD Substrate Integration
  6→ *
  7→ * Provides:
  8→ * - Shared perception state across components
  9→ * - Event recording for chat behavior feedback
 10→ * - Archetype and confidence accessors
 11→ */
 12→
 13→import { createContext, useContext, useState, useCallback, useRef, useEffect, ReactNode } from 'react';
 14→import { VisitorClassifier } from './classifier';
 15→import { SensorEvent, SensorEventType, VisitorArchetype } from './types';
 16→import type { PerceptionState } from './types';
 17→
 18→interface PerceptionContextValue {
 19→  perceptionState: PerceptionState | null;
 20→  updatePerceptionState: (state: PerceptionState) => void;
 21→  // Record events from any component (e.g., ChatBot)
 22→  recordEvent: (event: Omit<SensorEvent, 'sessionId'>) => void;
 23→  // Get current session ID
 24→  sessionId: string;
 25→  // Convenience accessors
 26→  archetype: VisitorArchetype | null;
 27→  confidence: number;
 28→  // Stability info for debugging
 29→  stability: {
 30→    consecutiveSameArchetype: number;
 31→    totalClassifications: number;
 32→  } | null;
 33→}
 34→
 35→const PerceptionContext = createContext<PerceptionContextValue | null>(null);
 36→
 37→export function PerceptionProvider({ children }: { children: ReactNode }) {
 38→  const [perceptionState, setPerceptionState] = useState<PerceptionState | null>(null);
 39→  // Shared classifier instance
 40→  const classifierRef = useRef<VisitorClassifier | null>(null);
 41→  const sessionIdRef = useRef<string>('');
 42→
 43→  // Initialize session ID on mount
 44→  if (!sessionIdRef.current) {
 45→    sessionIdRef.current = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
 46→  }
 47→
 48→  // Initialize classifier on mount
 49→  if (!classifierRef.current) {
 50→    classifierRef.current = new VisitorClassifier();
 51→  }
 52→
 53→  const updatePerceptionState = useCallback((state: PerceptionState) => {
 54→    setPerceptionState(state);
 55→  }, []);
 56→
 57→  /**
 58→   * Record an event from any component
 59→   * Used by ChatBot to feed chat behavior back into classification
 60→   */
 61→  const recordEvent = useCallback((eventWithoutSession: Omit<SensorEvent, 'sessionId'>) => {
 62→    if (!classifierRef.current) return;
 63→
 64→    const event: SensorEvent = {
 65→      ...eventWithoutSession,
 66→      sessionId: sessionIdRef.current,
 67→    };
 68→
 69→    classifierRef.current.addEvent(event);
 70→
 71→    // Re-classify and update state
 72→    const profile = classifierRef.current.classify();
 73→    const newState: PerceptionState = {
 74→      sessionId: sessionIdRef.current,
 75→      events: [], // Don't pass full event buffer
 76→      profile,
 77→      adaptations: {
 78→        projectOrder: 'default',
 79→        lastAdaptation: Date.now(),
 80→      },
 81→    };
 82→    setPerceptionState(newState);
 83→  }, []);
 84→
 85→  const value: PerceptionContextValue = {
 86→    perceptionState,
 87→    updatePerceptionState,
 88→    recordEvent,
 89→    sessionId: sessionIdRef.current,
 90→    archetype: perceptionState?.profile.archetype ?? null,
 91→    confidence: perceptionState?.profile.confidence ?? 0,
 92→    stability: perceptionState?.profile.stability ?? null,
 93→  };
 94→
 95→  return (
 96→    <PerceptionContext.Provider value={value}>
 97→      {children}
 98→    </PerceptionContext.Provider>
 99→  );
100→}
101→
102→export function usePerception(): PerceptionContextValue {
103→  const context = useContext(PerceptionContext);
104→  if (!context) {
105→    // Return safe defaults if used outside provider
106→    return {
107→      perceptionState: null,
108→      updatePerceptionState: () => {},
109→      recordEvent: () => {},
110→      sessionId: '',
111→      archetype: null,
112→      confidence: 0,
113→      stability: null,
114→    };
115→  }
116→  return context;
117→}
